def split_blocks(grid):
    """Split a grid into the two blocks on either side of its first full nonzero row or column (separator), as (blockA, blockB, axis)."""
    H, W = len(grid), len(grid[0])
    for i, r in enumerate(grid):
        if len(set(r)) == 1 and r[0] != 0:
            return grid[:i], grid[i+1:], 'row'
    for j in range(W):
        if len({r[j] for r in grid}) == 1 and grid[0][j] != 0:
            return [r[:j] for r in grid], [r[j+1:] for r in grid], 'col'
    return grid, grid, None

def and_overlay(blockA, blockB, color=2):
    """Cells where both same-shaped blocks are nonzero become color; other cells 0."""
    return [[color if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)] for ra, rb in zip(blockA, blockB)]
'''
